// strokeBuffer.ts (also re-exports everything below, because src/app/composition.ts imports buildStrokeLayer and makeUnderlayMaterial from here)
export class StrokeBuffer implements StrokeSink {
  constructor(capacity?: number /* default 4096, grows x2 */);
  push(r: StrokeRecord): void;            // packs a0.w = cls + FLAG_STRIDE*flags; throws on a bad class or a non-finite field
  readonly count: number;
  readonly data: Float32Array;            // subarray(0, count*16), a view
  classRange(cls: StrokeClass): { dMin: number; dMax: number; n: number };
  get(i: number, out: StrokeRecord): StrokeRecord;
  clsOf(i: number): StrokeClass; flagsOf(i: number): number;
}
export function emptyRecord(): StrokeRecord;
export { buildStrokeLayer, makeStrokeMaterial, type StrokeLayerEx, type StrokeChunkEx } from './strokeMaterial';
export { makeUnderlayMaterial } from './underlay';
export { makeRibbonGeometry } from './ribbonGeometry';
export { generateDebugStrokes } from './debugGen';

// strokeMaterial.ts
export const MAX_CHUNK = 4096; export const STORM_FIELD_BOUND = 2;
export interface StrokeChunkEx extends StrokeChunk { nUnder: number; center: Vector3 }
export interface StrokeLayerEx extends StrokeLayer { chunks: StrokeChunkEx[]; readonly material: ShaderMaterial; readonly drawCalls: number; dispose(): void }
export function makeStrokeMaterial(u: SharedUniforms, q: QualitySettings): ShaderMaterial;
export function buildStrokeLayer(buf: StrokeBuffer, u: SharedUniforms, q: QualitySettings): StrokeLayerEx;   // assignable to StrokeLayer; layer.ribbon = current shared ribbon (getter)

// ribbonGeometry.ts
export function makeRibbonGeometry(segments: 3 | 4 | 5): BufferGeometry;   // (segments+1)*2 verts, position=(s,w,0), indexed
export function sharedRibbon(segments: 3 | 4 | 5): BufferGeometry;         // cached shared instance per LOD

// underlay.ts
export const UNDERLAY_DEPTH_BIAS = 1e-3;
export const underlayVert: string; export const underlayFrag: string;
export function makeUnderlayMaterial(colorHex: number, u: SharedUniforms, side?: Side /* default FrontSide */): ShaderMaterial;

// debugGen.ts
export function generateDebugStrokes(sink: StrokeSink, rng: Rng, n?: number /* 64 */): void;

// glsl
export const strokeVert: string;  // src/strokes/glsl/stroke.vert.ts
export const strokeFrag: string;  // src/strokes/glsl/stroke.frag.ts (optional defines: HASHED_ALPHA, STK_DEBUG=1..5 for inspection)

// src/sky/skyGen.ts
export function generateSky(sink: StrokeSink, rng: Rng): void;          // UNDERPAINT, SKY_BAND, SWIRL(+UNDERLAYER shell), EDDY, WIND_JET; one rng draw seeds forkRng streams per class
export function generateUnderpaint(sink: StrokeSink, rng: Rng): void;
export function generateBands(sink: StrokeSink, rng: Rng): void;
export function generateFunnels(sink: StrokeSink, rng: Rng): void;     // SWIRL arms + shell, EDDY arms
export function generateJet(sink: StrokeSink, rng: Rng): void;
export const SKY_COUNTS: { underpaintRows: 60; underpaintCols: 50; band: 32000; swirl: readonly number[] /*[16000,14000]*/; swirlShell: readonly number[] /*[1600,1400]*/; eddy: 6000; eddyShell: 0; jetFilaments: 32; jetPerFilament: 75 };
export const SKY_CLASSES: readonly StrokeClass[];
export function skyDepthViolations(records: readonly StrokeRecord[]): string[];   // records outside CLASS_INFO[cls].dRange
// src/sky/backdrop.ts
export function createBackdrop(u: SharedUniforms, q: QualitySettings): Mesh;     // fullscreen triangle, renderOrder -1000, depthTest/depthWrite false, frustumCulled false, no logdepth; uniforms {...u, uBdLayers}
export function setBackdropQuality(backdrop: Mesh, q: QualitySettings): void;   // sets uBdLayers = q.backdropLayers (no recompile)
// src/sky/dust.ts
export function createDust(u: SharedUniforms, q: QualitySettings, rng: Rng): Points;  // max(q.dustCount, 30000) points, drawRange(0, q.dustCount), additive, logdepth, frustumCulled false, hand-set bounds

