  export function createCypressCore(material: Material): Mesh                // LatheGeometry, 97 profile points (96 segments) x 48 radial, world-space positions, name 'cypressCore'
  export const CYPRESS_CORE_COLOR = 0x0f1712, CYPRESS_TONGUES = 7, CYPRESS_STROKES = 18000, CYPRESS_UNDERLAYER_STROKES = 1500
Record layout:
  RING: u, v = the t = 0 position on the ring at radius rho_k (1 + 0.04 q3); d = ringGeom(si, k).d exactly; a1 = (L, 0, 0, W); a3 = (kappa in +-0.3, q1 = star index (0..10, moon 11), q2 = integer k, q3 in [-1, 1]).
  CYPRESS: a1 = (du, dv, dlnd, W) from the helix chord; a3 = (kappa in +-0.15, q1 = tongue 0..6, q2 = phi in [0, 2pi), q3 = 0).
  STAR_CORE: q1 = star index (informational only). MOON: q1..q3 = 0.

